void
CoinRain::update(float dt_sec)
{
  // First a single (untouchable) coin flies up above the sector.
  if (position.y > -32){
    float dist = -500 * dt_sec;
    position.y += dist;
    emerge_distance += dist;
  } // Then the first collectable coin drops from one of ten random positions.
  else if (counter==0){
    drop = gameRandom.rand(10);
    Sector::get().add<HeavyCoin>(Vector(position.x + 32.0f * static_cast<float>((drop < 5) ? -drop - 1 : drop - 4), -32.0f),
                                                              Vector(0, 0), m_count_stats, m_sprite_path);
    counter++;
    timer.start(DROP_TIME);
  } // Finally, the remaining coins drop in a determined but seemingly random order.
  else if (timer.check()){
    if (counter<10){
      drop += 7;
      if (drop >= 10) drop -=10;
      Sector::get().add<HeavyCoin>(Vector(position.x + 32.0f * static_cast<float>((drop < 5) ? -drop - 1 : drop - 4), -32.0f),
                                                                Vector(0, 0), m_count_stats, m_sprite_path);
      counter++;
      timer.start(DROP_TIME);
    } else {
      remove_me();
    }
  }
}

void
CoinRain::draw(DrawingContext& context)
{
  int layer;
  if (emerge_distance > 0) {
    layer = LAYER_OBJECTS - 5;
  } else {
    layer = LAYER_OBJECTS + 5;
  }
    m_physic.set_velocity_x(m_physic.get_velocity_x() * (1.f - (GROUND_FRICTION * (m_on_ice ? 0.5f : 1.f))));
  }
}

HitResponse
Rock::collision(MovingObject& other, const CollisionHit& hit)
{
  auto heavy_coin = dynamic_cast<HeavyCoin*> (&other);
  if (heavy_coin) {
    return ABORT_MOVE;
  }

  auto explosion = dynamic_cast<Explosion*> (&other);
  if (explosion) {
    return ABORT_MOVE;
  }

  // Why is it necessary to list exceptions here? Why doesn't the rock just not
  // affect object that have ABORT_MOVE on all collisions?
  auto litobject = dynamic_cast<LitObject*> (&other);
  if (litobject) {
  Rock::update(dt_sec);
}

HitResponse
Trampoline::collision(MovingObject& other, const CollisionHit& hit)
{
  auto heavy_coin = dynamic_cast<HeavyCoin*> (&other);
  if (heavy_coin) {
    return ABORT_MOVE;
  }
  auto player = dynamic_cast<Player*> (&other);
  //Trampoline works for player
  if (player && !is_grabbed())
  {
    player->override_velocity();
    if (player->m_does_buttjump)
      player->m_does_buttjump = false;
    float vy = player->get_physic().get_velocity_y();
    //player is falling down on trampoline
    if (hit.top && vy >= 0)
    {
  if(!m_is_active_flag)
     return;

  m_is_active_flag = false;

  if (m_is_glinting && m_can_glint && !m_holds_coins)
  {
    const int num_coins = get_coins_worth();

    for (int i = 0; i < num_coins; ++i)
    {
      const float coin_x = get_bbox().get_middle().x - 16.0f;
      const float coin_y = get_bbox().get_top() - 32.0f;

      Sector::get().add<HeavyCoin>(Vector(coin_x, coin_y),
                                   Vector(graphicsRandom.randf(-96.0f, 96.0f),
                                   0.0f));
    }
  }

  if (m_parent_dispenser != nullptr)
  {
    m_parent_dispenser->notify_dead();
  }

  // Start the dead-script.

